	ProfileBindingKindSeccompProfile ProfileBindingKind = "SeccompProfile"
	// ProfileBindingKindSelinuxProfile binds a SelinuxProfile.
	ProfileBindingKindSelinuxProfile ProfileBindingKind = "SelinuxProfile"
	// ProfileBindingKindAppArmorProfile binds an AppArmorProfile.
	ProfileBindingKindAppArmorProfile ProfileBindingKind = "AppArmorProfile"
	// SelectAllContainersImage is the image of a binding which applies to the
	// containers of every image.
	SelectAllContainersImage string = "*"
)

// AppliedBindingsAnnotation is set by the binding webhook on the pods it
// applied bindings to. Its value is the comma separated list of the names of
// the applied bindings in the namespace of the pod.
const AppliedBindingsAnnotation = "spo.x-k8s.io/profile-bindings"

// Reasons of a Ready condition which is not true, besides the reason
// Unavailable of a missing profile.
const (
	// ReasonProfileNotInstalled tells that the profile exists, but is not
	// installed on the nodes, so its state is reported in the message.
	ReasonProfileNotInstalled common.ConditionReason = "ProfileNotInstalled"
	// ReasonProfileKindDisabled tells that the profile kind is disabled in
	// the SPOD configuration, so that no node installs the profile and the
	// binding is not applied.
	ReasonProfileKindDisabled common.ConditionReason = "ProfileKindDisabled"
	// ReasonInvalidPodSelector tells that the podSelector of the binding
	// cannot be parsed, so that the binding webhook skips the binding for
	// every pod.
	ReasonInvalidPodSelector common.ConditionReason = "InvalidPodSelector"
	// ReasonProfileDeleting tells that the profile is being deleted and no
	// pod uses it anymore, so that the binding webhook rejects the pods
	// matching the binding.
	ReasonProfileDeleting common.ConditionReason = "ProfileDeleting"
	// ReasonBindingNotEnabled tells that the binding webhook does not select
	// the namespace of the binding, so that the binding is not applied.
	ReasonBindingNotEnabled common.ConditionReason = "BindingNotEnabled"
)

// ProfileBindingSpec defines the desired state of ProfileBinding.
type ProfileBindingSpec struct {
	// profileRef references the cluster-scoped SeccompProfile, SelinuxProfile
	// or AppArmorProfile to bind.
	// +required
	ProfileRef ProfileRef `json:"profileRef,omitzero"`
	// image specifies the container image name within pod containers to match to the profile.
	// Use the "*" string to bind the profile to all pods.
	// +required
	// +kubebuilder:validation:MinLength=1
	Image string `json:"image,omitempty"`
	// podSelector selects which pods this binding applies to. This field follows
	// standard label selector semantics. An empty or omitted podSelector matches
	// all pods in the namespace.
